            resolve_with_function_reuse(
                current,
                previous.map(|p| p.0),
                previous.map(|p| p.1),
                previous.map(|p| p.2),
                None,
            )
        });
        assert!(!refused);
        result.map(|(program, work)| (program, work.reused()))
    }
